package local.pocketchat;
import android.app.*;import android.widget.*;

final class DesignPrivacyUi {
  static void show(MainActivity a){Dialog dialog=new Dialog(a);LinearLayout root=DesignUi.screen(a),box=DesignUi.body(a,root,"隐私保护 / 环境自检",()->dialog.dismiss());box.addView(DesignUi.tabs(a,new String[]{"隐私保护","环境自检"},0,n->{if(n==1){dialog.dismiss();EnvironmentAuditUi.show(a);}}));DesignUi.note(box,"当前窗口："+Profiles.display(a,Profiles.slot(a)));LinearLayout levels=DesignUi.row(a);String[] names={"兼容","标准","强化"};for(int i=0;i<3;i++){final int level=i;LinearLayout card=DesignUi.card(a);card.addView(DesignUi.icon(a,"shield",i==a.session.privacy.level()?DesignUi.CYAN:DesignUi.MUTED,34));card.addView(DesignUi.text(a,names[i],15,DesignUi.TEXT));card.addView(DesignUi.text(a,i==0?"兼容优先":i==1?"默认保护":"限制更多读取",10,DesignUi.MUTED));card.setBackground(i==a.session.privacy.level()?DesignUi.surface(a,0xff0a2a5b,12,DesignUi.CYAN):DesignUi.surface(a,DesignUi.CARD,12,DesignUi.LINE));card.setOnClickListener(v->{dialog.dismiss();EnvironmentEditorUi.editTab(a,1);});LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);if(i>0)p.leftMargin=a.dp(6);levels.addView(card,p);}box.addView(levels);LinearLayout evidence=DesignUi.card(a);DesignUi.field(evidence,"实际保护状态",a.session.privacy.summary());DesignUi.addCard(box,evidence);DesignUi.action(box,"调整保护等级",true,()->{dialog.dismiss();EnvironmentEditorUi.editTab(a,1);});DesignUi.action(box,"检查本机信息 / 授权检查出口",false,()->EnvironmentAuditUi.show(a));DesignUi.action(box,"查看已记录的环境变化",false,()->EnvironmentAuditUi.show(a));TextView warning=DesignUi.text(a,"保护与检查只覆盖已列出的路径，不承诺 VPN 隐身或 100% 防封号。",12,DesignUi.RED);warning.setPadding(a.dp(12),a.dp(12),a.dp(12),a.dp(12));warning.setBackground(DesignUi.surface(a,0xff2b1722,10,0xff713747));DesignUi.addCard(box,warning);dialog.setContentView(root);dialog.show();dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(-1,-1);}
}
